+</head>
+<body>
+    <div class="game-container">
+        <div class="game-board" id="game-board"></div>
+        <div class="score" id="score">Score: 0</div>
+        <div class="high-score" id="high-score">High Score: 0</div>
+        <div class="start-game-overlay" id="start-game-overlay">
+            <h1>Snake Game</h1>
+            <p>Use arrow keys or touch screen to control the snake.</p>
+            <button class="start-game-button" id="start-game-button">Start Game</button>
+        </div>
+        <div class="game-over-overlay" id="game-over-overlay">
+            <h1>Game Over</h1>
+            <p>Final Score: <span id="final-score">0</span></p>
+            <button class="replay-button" id="replay-button">Replay</button>
+        </div>
+    </div>
+    <script>
+        let snake = [];
+        let food = null;
+        let score = 0;
+        let highScore = 0;
+        let direction = 'right';
+        let gameInterval = null;
+        let audioContext = new AudioContext();
+        let eatSound = null;
+        let gameOverSound = null;
+        
+        // Initialize game board
+        const gameBoard = document.getElementById('game-board');
+        for (let i = 0; i < 20; i++) {
+            for (let j = 0; j < 20; j++) {
+                const cell = document.createElement('div');
+                cell.style.width = '20px';
+                cell.style.height = '20px';
+                cell.style.border = '1px solid #fff';
+                gameBoard.appendChild(cell);
+            }
+        }
+        
+        // Initialize snake
+        for (let i = 0; i < 5; i++) {
+            const snakePart = document.createElement('div');
+            snakePart.className = 'snake-part';
+            snakePart.style.left = `${i * 20}px`;
+            snakePart.style.top = '0px';
+            gameBoard.appendChild(snakePart);
+            snake.push(snakePart);
+        }
+        
+        // Initialize food
+        food = document.createElement('div');
+        food.className = 'food';
+        food.style.left = `${Math.floor(Math.random() * 20) * 20}px`;
+        food.style.top = `${Math.floor(Math.random() * 20) * 20}px`;
+        gameBoard.appendChild(food);
+        
+        // Initialize score and high score
+        const scoreElement = document.getElementById('score');
+        const highScoreElement = document.getElementById('high-score');
+        scoreElement.textContent = `Score: ${score}`;
+        highScoreElement.textContent = `High Score: ${highScore}`;
+        
+        // Start game
+        document.getElementById('start-game-button').addEventListener('click', () => {
+            startGame();
+        });
+        
+        // Handle key presses
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (e.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            } else if (e.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (e.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            }
+        });
+        
+        // Handle touch screen
+        gameBoard.addEventListener('touchstart', (e) => {
+            const touch = e.touches[0];
+            const x = touch.clientX;
+            const y = touch.clientY;
+            if (x < gameBoard.offsetWidth / 2 && y < gameBoard.offsetHeight / 2) {
+                direction = 'up';
+            } else if (x < gameBoard.offsetWidth / 2 && y > gameBoard.offsetHeight / 2) {
+                direction = 'left';
+            } else if (x > gameBoard.offsetWidth / 2 && y < gameBoard.offsetHeight / 2) {
+                direction = 'right';
+            } else if (x > gameBoard.offsetWidth / 2 && y > gameBoard.offsetHeight / 2) {
+                direction = 'down';
+            }
+        });
+        
+        // Update game state
+        function update() {
+            // Move snake
+            for (let i = snake.length - 1; i > 0; i--) {
+                snake[i].style.left = snake[i - 1].style.left;
+                snake[i].style.top = snake[i - 1].style.top;
+            }
+            if (direction === 'up') {
+                snake[0].style.top = `${parseInt(snake[0].style.top) - 20}px`;
+            } else if (direction === 'down') {
+                snake[0].style.top = `${parseInt(snake[0].style.top) + 20}px`;
+            } else if (direction === 'left') {
+                snake[0].style.left = `${parseInt(snake[0].style.left) - 20}px`;
+            } else if (direction === 'right') {
+                snake[0].style.left = `${parseInt(snake[0].style.left) + 20}px`;
+            }
+            
+            // Check collision with food
+            if (snake[0].style.left === food.style.left && snake[0].style.top === food.style.top) {
+                // Eat food
+                eatSound = audioContext.createBufferSource();
+                eatSound.connect(audioContext.destination);
+                eatSound.start();
+                score++;
+                scoreElement.textContent = `Score: ${score}`;
+                
+                // Generate new food
+                food.style.left = `${Math.floor(Math.random() * 20) * 20}px`;
+                food.style.top = `${Math.floor(Math.random() * 20) * 20}px`;
+                
+                // Add new snake part
+                const newSnakePart = document.createElement('div');
+                newSnakePart.className = 'snake-part';
+                newSnakePart.style.left = snake[snake.length - 1].style.left;
+                newSnakePart.style.top = snake[snake.length - 1].style.top;
+                gameBoard.appendChild(newSnakePart);
+                snake.push(newSnakePart);
+            }
+            
+            // Check collision with wall or self
+            if (parseInt(snake[0].style.left) < 0 || parseInt(snake[0].style.left) >= gameBoard.offsetWidth ||
+                parseInt(snake[0].style.top) < 0 || parseInt(snake[0].style.top) >= gameBoard.offsetHeight) {
+                // Game over
+                gameOverSound = audioContext.createBufferSource();
+                gameOverSound.connect(audioContext.destination);
+                gameOverSound.start();
+                clearInterval(gameInterval);
+                document.getElementById('game-over-overlay').style.display = 'flex';
+                document.getElementById('final-score').textContent = score;
+                if (score > highScore) {
+                    highScore = score;
+                    highScoreElement.textContent = `High Score: ${highScore}`;
+                }
+            } else {
+                for (let i = 1; i < snake.length; i++) {
+                    if (snake[0].style.left === snake[i].style.left && snake[0].style.top === snake[i].style.top) {
+                        // Game over
+                        gameOverSound = audioContext.createBufferSource();
+                        gameOverSound.connect(audioContext.destination);
+                        gameOverSound.start();
+                        clearInterval(gameInterval);
+                        document.getElementById('game-over-overlay').style.display = 'flex';
+                        document.getElementById('final-score').textContent = score;
+                        if (score > highScore) {
+                            highScore = score;
+                            highScoreElement.textContent = `High Score: ${highScore}`;
+                        }
+                    }
+                }
+            }
+        }
+        
+        // Start game interval
+        function startGame() {
+            gameInterval = setInterval(update, 100);
+            document.getElementById('start-game-overlay').style.display = 'none';
+        }
+        
+        // Replay game
+        document.getElementById('replay-button').addEventListener('click', () => {
+            // Reset game state
+            snake = [];
+            food = null;
+            score = 0;
+            direction = 'right';
+            
+            // Remove all snake parts and food
+            while (gameBoard.firstChild) {
+                gameBoard.removeChild(gameBoard.firstChild);
+            }
+            
+            // Initialize game board
+            for (let i = 0; i < 20; i++) {
+                for (let j = 0; j < 20; j++) {
+                    const cell = document.createElement('div');
+                    cell.style.width = '20px';
+                    cell.style.height = '20px';
+                    cell.style.border = '1px solid #fff';
+                    gameBoard.appendChild(cell);
+                }
+            }
+            
+            // Initialize snake
+            for (let i = 0; i < 5; i++) {
+                const snakePart = document.createElement('div');
+                snakePart.className = 'snake-part';
+                snakePart.style.left = `${i * 20}px`;
+                snakePart.style.top = '0px';
+                gameBoard.appendChild(snakePart);
+                snake.push(snakePart);
+            }
+            
+            // Initialize food
+            food = document.createElement('div');
+            food.className = 'food';
+            food.style.left = `${Math.floor(Math.random() * 20) * 20}px`;
+            food.style.top = `${Math.floor(Math.random() * 20) * 20}px`;
+            gameBoard.appendChild(food);
+            
+            // Initialize score and high score
+            scoreElement.textContent = `Score: ${score}`;
+            highScoreElement.textContent = `High Score: ${highScore}`;
+            
+            // Start game
+            startGame();
+        });
+    </script>
+</body>
+</html>

